@push('scripts')<script>(()=>{const rows=document.getElementById('rows'),template=document.getElementById('row');let i=0;const money=n=>'Bs '+n.toFixed(2).replace('.',',');function update(){let total=0;rows.querySelectorAll('tr').forEach(row=>{const price=Number(row.querySelector('select').selectedOptions[0]?.dataset.price||0),quantity=Number(row.querySelector('input').value||0),sub=price*quantity;row.querySelector('.price').textContent=money(price);row.querySelector('.subtotal').textContent=money(sub);total+=sub});document.getElementById('total').textContent=money(total)}function add(){const tbody=document.createElement('tbody');tbody.innerHTML=template.innerHTML.replaceAll('INDEX',String(i++));const row=tbody.firstElementChild;rows.appendChild(row);row.addEventListener('input',update);row.querySelector('button').addEventListener('click',()=>{if(rows.children.length>1)row.remove();update()});update()}document.getElementById('add').addEventListener('click',add);add()})();</script>@endpush
